// Menu_SoundOptions constants
//---------------------------------------------------------------------------------------------------------

#define SLIDER_SFX_SOUND	( SFX_ATTACK_SWORD )
#define SLIDER_MUSIC_SOUND  ( -1 )

#define k_menu_sound_options_title					( STRING_IDS::MENU_SOUND_OPTIONS_TITLE )

#define k_slider_sfx_frame_bkg						( MENU_F_MENU_SLIDER_EMPTY )
#define k_slider_sfx_frame_fill						( MENU_F_MENU_SLIDER_FILL )
#define k_slider_sfx_button_nrm						( MENU_F_MENU_SLIDER_SFX_NORMAL )
#define k_slider_sfx_button_pressed					( MENU_F_MENU_SLIDER_SFX_PRESSED )
#define k_slider_sfx_x								( 242 ) 
#define k_slider_sfx_y								( 144 )
#define k_slider_sfx_w								( m_sprite->GetFrameWidth( k_slider_sfx_frame_bkg ) )
#define k_slider_sfx_h								( m_sprite->GetFrameHeight( k_slider_sfx_frame_bkg ) )

#define k_slider_music_frame_bkg					( MENU_F_MENU_SLIDER_EMPTY )
#define k_slider_music_frame_fill					( MENU_F_MENU_SLIDER_FILL )
#define k_slider_music_button_nrm					( MENU_F_MENU_SLIDER_MUSIC_NORMAL )
#define k_slider_music_button_pressed				( MENU_F_MENU_SLIDER_MUSIC_PRESSED )
#define k_slider_music_x							( 241 ) 
#define k_slider_music_y							( 236 )
#define k_slider_music_w							( m_sprite->GetFrameWidth( k_slider_sfx_frame_bkg ) )
#define k_slider_music_h							( m_sprite->GetFrameHeight( k_slider_sfx_frame_bkg ) )

