//---------------------------------------------------------------------------------------------------------


#define BORDER_LEFT_X		( 74 )
#define BORDER_LEFT_Y		( 55 )
#define BORDER_RIGHT_X		( 405 )
#define BORDER_RIGHT_Y		( 287 )

void Menu_SoundOptions::DrawMenuBackground()
{
	IVideoDriver *driver = __IRR_DRIVER();
	
	driver->draw2DRectangle(SColor(200, 0, 0, 0), r2i(BORDER_LEFT_X, BORDER_LEFT_Y, BORDER_RIGHT_X, BORDER_RIGHT_Y));

	//draw border
	m_sprite->PaintFrame( MENU_F_MENU_HORIZONTAL_LINE, (BORDER_LEFT_X + BORDER_RIGHT_X) / 2, BORDER_LEFT_Y);
	m_sprite->PaintFrame( MENU_F_MENU_HORIZONTAL_LINE, (BORDER_LEFT_X + BORDER_RIGHT_X) / 2, BORDER_RIGHT_Y);
	m_sprite->PaintFrame( MENU_F_MENU_VERTICAL_LINE_MAIN_MENU, BORDER_LEFT_X, (BORDER_LEFT_Y + BORDER_RIGHT_Y) / 2);
	m_sprite->PaintFrame( MENU_F_MENU_VERTICAL_LINE_MAIN_MENU, BORDER_RIGHT_X, (BORDER_LEFT_Y + BORDER_RIGHT_Y) / 2);
	
	m_sprite->PaintFrame( MENU_F_MENU_UPPER_LEFT_ARROW , BORDER_LEFT_X, BORDER_LEFT_Y );	
	m_sprite->PaintFrame( MENU_F_MENU_UPPER_RIGHT_ARROW, BORDER_RIGHT_X, BORDER_LEFT_Y );	
	m_sprite->PaintFrame( MENU_F_MENU_BOTTOM_RIGHT_ARROW, BORDER_RIGHT_X, BORDER_RIGHT_Y );	
	m_sprite->PaintFrame( MENU_F_MENU_BOTTOM_LEFT_ARROW , BORDER_LEFT_X, BORDER_RIGHT_Y );	

}

//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------
void Menu_SoundOptions::Draw()
{
	if (!m_isInitialized) return;

	if( !m_isIngame ) 
		DrawMenuBackground();

	// Draw controls
	//-------------------------------
	VisualControls_Draw();
}


//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------
void Menu_SoundOptions::Update( float dt )
{
	if( !m_isInitialized )
		return;

	IMenu::Update( dt );

	UpdateText();
}

//---------------------------------------------------------------------------------------------------------
//---------------------------------------------------------------------------------------------------------

void Menu_SoundOptions::UpdateText()
{
	TCHAR temp[50];

	stringw text;

	text = _TXT_INT(k_text_sfx_text);
	text += L" ";
	text += stringw( m_sfxSlider->GetValue() );	
	text += L"%";
	m_sfxText->SetText( text );

	text = _TXT_INT(k_text_music_text);
	text += L" ";
	text += stringw( m_musicSlider->GetValue() );	
	text += L"%";
	m_musicText->SetText( text );
}

//---------------------------------------------------------------------------------------------------------
// Perform Visual control actions
//---------------------------------------------------------------------------------------------------------
void Menu_SoundOptions::VisualControlDoAction( IVisualControl* visual_control, int action_id )
{
	switch ( action_id ) 
	{
		case action_back:
			{
				Transition_Start( transition_hide, action_back_trans );
			}
			break;
		case action_back_trans:
			{
				if ( m_isIngame ) 
				{
					GetParent()->Transition_Start( transition_show );
					m_backClicked = true;	
				}
				else
				{
					GetParent()->SubMenu_Change( "Menu_Options" );
				}
			}
			break;
		case action_slider_sfx:
			{
				__MGR_SOUNDS()->setSFxVolume(m_sfxSlider->GetValue() / 100.f);	
			}
			break;
		case action_slider_music:
			{
				__MGR_SOUNDS()->setMusicVolume(m_musicSlider->GetValue() / 100.f);	
			}
			break;
	};
}
